commands.command:
set -eu
SECDIR=/run/branch-stock-secrets
install -d -m 700 "$SECDIR"
umask 077
STOCK_PASSWORD=[REDACTED]]] rand -base64 36 | tr -d '\n')
AUDITOR_PASSWORD=[REDACTED]]] rand -base64 36 | tr -d '\n')
[ "$STOCK_PASSWORD" != "$AUDITOR_PASSWORD" ]
runuser -u postgres -- createdb branch_stock
runuser -u postgres -- psql -X -v ON_ERROR_STOP=1 --dbname=branch_stock --file=/srv/legacy2/database-reader-writer-roles/stock.sql >/dev/null
runuser -u postgres -- psql -X -v ON_ERROR_STOP=1 --dbname=postgres >/dev/null <<SQL
BEGIN;
CREATE ROLE stock_app LOGIN PASSWORD '$STOCK_PASSWORD';
CREATE ROLE auditor LOGIN PASSWORD '$AUDITOR_PASSWORD';
REVOKE ALL ON DATABASE branch_stock FROM PUBLIC;
GRANT CONNECT ON DATABASE branch_stock TO stock_app, auditor;
ALTER ROLE stock_app SET search_path = public;
ALTER ROLE auditor SET search_path = public;
COMMIT;
SQL
runuser -u postgres -- psql -X -v ON_ERROR_STOP=1 --dbname=branch_stock >/dev/null <<'SQL'
BEGIN;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA public FROM PUBLIC;
REVOKE ALL ON TABLE stock, supplier_costs FROM stock_app, auditor;
GRANT USAGE ON SCHEMA public TO stock_app, auditor;
GRANT SELECT ON TABLE stock TO stock_app;
GRANT UPDATE (quantity) ON TABLE stock TO stock_app;
GRANT SELECT ON TABLE stock, supplier_costs TO auditor;
COMMIT;
SQL
printf 'stock_app:%s\nauditor:%s\n' "$STOCK_PASSWORD" "$AUDITOR_PASSWORD" > "$SECDIR/credentials"
printf '%s' '[REDACTED_ENCODED_BLOB]==' | base64 -d > "$SECDIR/public.pem"
openssl pkeyutl -encrypt -pubin -inkey "$SECDIR/public.pem" -in "$SECDIR/credentials" -out "$SECDIR/credentials.enc" -pkeyopt rsa_padding_mode:oaep
printf 'credential_ciphertext_b64='; base64 -w0 "$SECDIR/credentials.enc"; printf '\n'
rm -f "$SECDIR/credentials" "$SECDIR/public.pem" "$SECDIR/credentials.enc"
rmdir "$SECDIR"
printf '%s\n' 'deployed-counts:'
runuser -u postgres -- psql -X -A -t -v ON_ERROR_STOP=1 --dbname=branch_stock -c "SELECT 'stock='||count(*) FROM stock UNION ALL SELECT 'supplier_costs='||count(*) FROM supplier_costs ORDER BY 1;"
printf '%s\n' 'role-login-summary:'
runuser -u postgres -- psql -X -A -t -v ON_ERROR_STOP=1 --dbname=postgres -c "SELECT rolname||':login='||rolcanlogin||':super='||rolsuper||':createdb='||rolcreatedb||':createrole='||rolcreaterole FROM pg_roles WHERE rolname IN ('stock_app','auditor') ORDER BY rolname;"
